import {solarPosition,instant,sampleSpace,dayStudy,validateStudy,wrap,clamp} from './solar.js';
import {Scene} from './scene.js';
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const example=()=>({version:1,example:true,site:{name:'Bengaluru · example',lat:12.9716,lon:77.5946,offset:5.5},spaces:[{id:uid(),name:'Living room terrace',x:0,y:0,w:9,d:6,z:3},{id:uid(),name:'East balcony',x:8,y:0,w:3,d:5,z:3}],blockers:[{id:uid(),name:'Neighbouring building',x:15,y:-11,w:9,d:10,h:18,base:0},{id:uid(),name:'North building',x:-10,y:19,w:11,d:8,h:13,base:0}]});
let study=example();try{const saved=localStorage.getItem('sunlight-study-v1');if(saved)study=validateStudy(JSON.parse(saved));}catch{}
let selected=study.spaces[0].id,view='3d',drawMode=false,minute=570,day=new Date().toISOString().slice(0,10),sun,playTimer,dayCache,yearDays=null,worker=null,stream=null,recorder=null,recordTimer=null,cameraActive=false,sensorActive=false,editing=null,toastTimer,yearGeneration=0,recordUrl=null;
let cal={heading:110,pitch:0,fov:65,offset:0};
const space=()=>study.spaces.find(s=>s.id===selected)||study.spaces[0];
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),6000);}
function save(){try{localStorage.setItem('sunlight-study-v1',JSON.stringify(study));}catch{toast('Browser storage is full or unavailable. Export your study to keep it.');}}
function invalidate(){dayCache=null;yearDays=null;yearGeneration++;worker?.terminate();worker=null;$('yearResult').hidden=true;$('yearEmpty').hidden=false;$('yearBtn').disabled=false;$('yearBtn').textContent='Calculate full year';}
function changed(){study.example=false;invalidate();save();render();}
function render(){
  sun=solarPosition(instant(day,minute,study.site.offset),study.site.lat,study.site.lon);
  const s=space(),fraction=sampleSpace(s,sun,study.blockers,12);
  $('siteName').textContent=study.site.name;$('siteCoords').textContent=`${study.site.lat.toFixed(4)}°, ${study.site.lon.toFixed(4)}°`;
  $('date').value=day;$('time').value=minute;$('timeLabel').textContent=formatTime(minute);
  $('sunPercent').textContent=Math.round(fraction*100)+'%';$('sunFill').style.width=(fraction*100)+'%';
  $('exposureDescription').textContent=sun.altitude<=0?'The sun is below the horizon.':fraction===1?'The model shows unobstructed sunlight across this space.':fraction===0?'The model places this space entirely in shade.':'Part of this space is shaded by the modelled blockers.';
  const key=day+selected;if(!dayCache||dayCache.key!==key)dayCache={key,...dayStudy(day,study.site,s,study.blockers)};
  $('sunHours').textContent=dayCache.hours.toFixed(1)+' h';$('dayHours').textContent=dayCache.daylight.toFixed(1)+' h';
  $('sunDirection').textContent=['North','North-east','East','South-east','South','South-west','West','North-west'][Math.round(sun.azimuth/45)%8];
  $('sunAngles').textContent=`${sun.azimuth.toFixed(1)}° bearing · ${sun.altitude.toFixed(1)}° elevation`;
  $('modelBadge').textContent=view==='camera'?'ALIGNMENT ESTIMATE':study.example?'EXAMPLE MODEL':'MANUAL MODEL';
  $('spaceList').innerHTML=study.spaces.map(p=>`<button class="space-item ${p.id===selected?'active':''}" data-space="${esc(p.id)}" aria-pressed="${p.id===selected}"><span class="space-icon" aria-hidden="true">▱</span><span><strong>${esc(p.name)}</strong><small>${(p.w*p.d).toFixed(1)} m² · ${p.z} m elevation</small></span><span class="chevron">›</span></button>`).join('');
  $('geometrySummary').innerHTML=`<span>${s.w.toFixed(1)} × ${s.d.toFixed(1)} m</span><span>${s.z.toFixed(1)} m elevation</span>`;
  $('blockerCount').textContent=study.blockers.length;
  $('blockerList').innerHTML=study.blockers.map(b=>`<button class="blocker-item" data-blocker="${esc(b.id)}"><span class="block-icon" aria-hidden="true">▥</span><span><strong>${esc(b.name)}</strong><small>${b.h} m tall · ${Math.hypot(b.x-s.x,b.y-s.y).toFixed(1)} m centre distance</small></span><span>›</span></button>`).join('')||'<p class="fineprint">No blockers mapped. All surrounding space is treated as open.</p>';
  $('yearSpace').textContent=s.name;$('accuracyTitle').textContent=study.example?'A model, not a measurement':'Only as accurate as your measurements';
  $('accuracyText').textContent=study.example?'Replace the example dimensions with your measurements. Unmapped objects and clouds are not included.':'Manual geometry. Missing walls, trees, buildings, and clouds are not included. Validate against sunlight observed on site.';
  scene.draw();
}
function formatTime(m){return `${String(Math.floor(m/60)).padStart(2,'0')}:${String(Math.floor(m%60)).padStart(2,'0')}`;}
function setView(v){view=v;drawMode=false;$('drawSpace').classList.remove('drawing');document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.view===v)));$('modelActions').hidden=v==='camera';$('cameraActions').hidden=v!=='camera';$('cameraStart').hidden=v!=='camera'||cameraActive;$('camera').hidden=v!=='camera'||!cameraActive;$('stageCaption').hidden=v==='camera';$('stageHint').textContent=v==='3d'?'Drag to orbit · Scroll to zoom':v==='plan'?'True north is up · Scroll to zoom':'Hold upright · Calibrate before comparing';if(v!=='camera')closeCamera();render();}
const scene=new Scene($('scene'),()=>({study,selected,view,sun,day,minute,cal,drawMode,cameraActive}), (a,b)=>{
  drawMode=false;$('drawSpace').classList.remove('drawing');if(!a){$('stageHint').textContent='Opening marked on frozen frame';toast('Frame annotation saved. Use the measured floor plan for area sunlight calculations.');return;}
  const w=Math.abs(a[0]-b[0]),d=Math.abs(a[1]-b[1]);openEditor('space',{id:uid(),name:'New open space',x:+((a[0]+b[0])/2).toFixed(2),y:+((a[1]+b[1])/2).toFixed(2),w:+Math.max(.1,w).toFixed(2),d:+Math.max(.1,d).toFixed(2),z:space().z},true);
});
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
$('spaceList').onclick=e=>{const b=e.target.closest('[data-space]');if(b){selected=b.dataset.space;invalidate();render();}};
$('blockerList').onclick=e=>{const b=e.target.closest('[data-blocker]');if(b)openEditor('blocker',study.blockers.find(o=>o.id===b.dataset.blocker));};
$('date').onchange=()=>{if(!$('date').value||!$('date').validity.valid)return;const oldYear=day.slice(0,4);day=$('date').value;dayCache=null;if(oldYear!==day.slice(0,4))invalidate();render();};
$('time').oninput=()=>{minute=+$('time').value;render();};
$('nowBtn').onclick=()=>{const n=new Date(Date.now()+study.site.offset*3600000),d=n.toISOString().slice(0,10);if(d.slice(0,4)!==day.slice(0,4))invalidate();day=d;minute=n.getUTCHours()*60+n.getUTCMinutes();dayCache=null;render();};
function stopPlay(){clearInterval(playTimer);playTimer=null;$('playBtn').textContent='▶';$('playBtn').setAttribute('aria-label','Play day');}
$('playBtn').onclick=()=>{if(playTimer){stopPlay();return;}$('playBtn').textContent='Ⅱ';$('playBtn').setAttribute('aria-label','Pause day');playTimer=setInterval(()=>{minute=(minute+5)%1440;render();},110);};
document.querySelectorAll('[data-season]').forEach(b=>b.onclick=()=>{day=day.slice(0,4)+'-'+b.dataset.season;dayCache=null;render();});
$('resetView').onclick=()=>scene.reset();
$('drawSpace').onclick=()=>{if(study.spaces.length>=25){toast('This study supports up to 25 spaces.');return;}setView('plan');drawMode=true;$('drawSpace').classList.add('drawing');$('stageHint').textContent='Drag a rectangle over the open space';toast('Drag a rectangle, then enter its measured dimensions.');};
$('addBlocker').onclick=()=>{if(study.blockers.length>=100){toast('This study supports up to 100 blockers.');return;}openEditor('blocker',{id:uid(),name:'New blocker',x:10,y:10,w:5,d:5,h:10,base:0},true);};
$('editSpace').onclick=()=>openEditor('space',space());
function openEditor(type,obj,isNew=false){editing={type,obj,isNew};$('editorTitle').textContent=(isNew?'Add ':'Edit ')+(type==='space'?'open space':'blocker');const labels={x:'East of origin (m)',y:'North of origin (m)',w:'Width east–west (m)',d:'Depth north–south (m)',z:'Floor elevation (m)',h:'Height above base (m)',base:'Base elevation (m)'};
  const keys=type==='space'?['x','y','w','d','z']:['x','y','w','d','base','h'];
  $('editorFields').innerHTML=`<label>Name<input name="name" value="${esc(obj.name)}" maxlength="100" required></label><div class="field-grid">${keys.map(k=>`<label>${labels[k]}<input name="${k}" type="number" value="${obj[k]}" step="any" min="${['w','d','h'].includes(k)?'.1':['x','y'].includes(k)?'-1000':'-100'}" max="${['w','d'].includes(k)?'500':'1000'}" required></label>`).join('')}</div><p class="fineprint">All dimensions are metres. Positive east and north positions share one origin. Elevations share one datum. For a roof or overhang, use a thin blocker at its actual base elevation.</p>`;
  $('deleteObject').hidden=isNew||(type==='space'&&study.spaces.length===1);$('editor').showModal();}
$('editorForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),obj={...editing.obj};for(const [k,v] of f)obj[k]=k==='name'?v:Number(v);const list=editing.type==='space'?study.spaces:study.blockers;if(editing.isNew)list.push(obj);else list[list.findIndex(x=>x.id===obj.id)]=obj;if(editing.type==='space')selected=obj.id;$('editor').close();changed();};
$('deleteObject').onclick=()=>{const key=editing.type==='space'?'spaces':'blockers';study[key]=study[key].filter(x=>x.id!==editing.obj.id);if(!study.spaces.some(s=>s.id===selected))selected=study.spaces[0].id;$('editor').close();changed();};
$('newStudy').onclick=()=>{if(!confirm('Start a new empty study? Export first if you want to keep this one.'))return;study={version:1,example:false,site:{...study.site,name:study.site.name.replace(' · example','')},spaces:[{id:uid(),name:'My open space',x:0,y:0,w:5,d:4,z:0}],blockers:[]};selected=study.spaces[0].id;changed();openEditor('space',space());};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
for(const id of ['helpBtn','accuracyBtn'])$(id).onclick=()=>$('helpDialog').showModal();
$('locationBtn').onclick=()=>{const s=study.site;$('locName').value=s.name;$('lat').value=s.lat;$('lon').value=s.lon;$('offset').value=s.offset;$('locationDialog').showModal();};
$('locationForm').onsubmit=e=>{e.preventDefault();study.site={name:$('locName').value,lat:+$('lat').value,lon:+$('lon').value,offset:+$('offset').value};$('locationDialog').close();changed();};
$('gpsBtn').onclick=()=>{if(!navigator.geolocation){$('gpsStatus').textContent='Location is unavailable. Enter coordinates manually.';return;}$('gpsStatus').textContent='Locating…';$('gpsBtn').disabled=true;navigator.geolocation.getCurrentPosition(p=>{$('lat').value=p.coords.latitude.toFixed(6);$('lon').value=p.coords.longitude.toFixed(6);$('offset').value=-new Date().getTimezoneOffset()/60;$('locName').value='My property';$('gpsStatus').textContent=`Reported GPS accuracy: ±${Math.round(p.coords.accuracy)} m. UTC offset follows this device; verify it for the property.`;$('gpsBtn').disabled=false;},e=>{$('gpsStatus').textContent='Location unavailable: '+e.message+'. You can enter coordinates manually.';$('gpsBtn').disabled=false;},{enableHighAccuracy:true,timeout:15000,maximumAge:0});};
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000);}
$('exportBtn').onclick=()=>{download(new Blob([JSON.stringify(study,null,2)],{type:'application/json'}),'sunlight-study.json');toast('Study exported with location, spaces, and blockers.');};
$('importBtn').onclick=()=>$('importFile').click();$('importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error('Study file is too large');const next=validateStudy(JSON.parse(await file.text()));study=next;selected=study.spaces[0].id;invalidate();save();render();toast('Study imported.');}catch(e){toast('Could not import: '+e.message);}finally{$('importFile').value='';}};
$('yearBtn').onclick=()=>{worker?.terminate();const generation=++yearGeneration;$('yearBtn').disabled=true;$('yearBtn').textContent='Calculating…';try{worker=new Worker(new URL('./year-worker.js',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(generation!==yearGeneration)return;if(data.progress)$('yearBtn').textContent=`${data.progress} days calculated`;if(data.days){yearDays=data.days;$('yearEmpty').hidden=true;$('yearResult').hidden=false;$('yearBtn').disabled=false;$('yearBtn').textContent='Recalculate year';drawYear();worker.terminate();worker=null;}};worker.onerror=()=>{toast('Year calculation failed. Try again with fewer blockers.');$('yearBtn').disabled=false;$('yearBtn').textContent='Retry calculation';worker?.terminate();};worker.postMessage({year:Number(day.slice(0,4)),site:study.site,space:space(),blockers:study.blockers});}catch{toast('This browser cannot start the year calculation.');$('yearBtn').disabled=false;}};
function drawYear(){if(!yearDays)return;const canvas=$('yearChart'),r=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=r.width*dpr;canvas.height=r.height*dpr;const c=canvas.getContext('2d'),w=canvas.width/yearDays.length,h=canvas.height/72;yearDays.forEach((d,i)=>d.samples.forEach((s,j)=>{c.fillStyle=s.altitude<=0?'#253340':s.fraction===0?'#885466':`rgb(${Math.round(152+103*s.fraction)} ${Math.round(98+104*s.fraction)} ${Math.round(103-1*s.fraction)})`;c.fillRect(i*w,(71-j)*h,Math.ceil(w),Math.ceil(h));}));const avg=yearDays.reduce((sum,d)=>sum+d.hours,0)/yearDays.length;$('yearSummary').textContent=`${avg.toFixed(1)} sun-equivalent hours per day · annual average`;$('yearChart').setAttribute('aria-label',`${yearDays.length}-day sunlight map for ${space().name}. Annual average ${avg.toFixed(1)} sun-equivalent hours per day.`);}
new ResizeObserver(drawYear).observe($('yearChart'));
$('yearChart').onclick=e=>{if(!yearDays)return;const r=e.target.getBoundingClientRect(),i=clamp(Math.floor((e.clientX-r.left)/r.width*yearDays.length),0,yearDays.length-1);day=yearDays[i].day;minute=clamp(Math.floor((1-(e.clientY-r.top)/r.height)*1440),0,1439);dayCache=null;render();toast(`${day} at ${formatTime(minute)} · ${yearDays[i].hours.toFixed(1)} sun-equivalent hours for the day`);};
$('startCamera').onclick=async()=>{if(!navigator.mediaDevices?.getUserMedia){toast('Camera needs a supported browser over HTTPS. The measured study still works.');return;}try{$('startCamera').disabled=true;stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:1920}},audio:false});$('camera').srcObject=stream;await $('camera').play();cameraActive=true;$('camera').hidden=false;$('cameraStart').hidden=true;syncCameraAspect();scene.draw();toast('Camera opened. Calibrate the heading, horizon, and lens before using the overlay.');}catch(e){stream?.getTracks().forEach(t=>t.stop());stream=null;toast('Camera unavailable: '+e.message);}finally{$('startCamera').disabled=false;}};
function syncCameraAspect(){if(cameraActive&&$('camera').videoWidth){const ratio=$('camera').videoHeight/$('camera').videoWidth;const width=$('stage').clientWidth;$('stage').style.height=Math.round(width*ratio)+'px';}scene.draw();}
window.addEventListener('resize',()=>{if(view==='camera')syncCameraAspect();});
function closeCamera(){if(recorder?.state==='recording')recorder.stop();clearTimeout(recordTimer);stream?.getTracks().forEach(t=>t.stop());stream=null;cameraActive=false;$('camera').srcObject=null;$('camera').hidden=true;$('stage').style.height='';scene.frozen=null;scene.mark=null;drawMode=false;$('markCamera').textContent='▣ Mark opening';disableSensors();}
$('stopCamera').onclick=()=>{closeCamera();$('cameraStart').hidden=false;scene.draw();};
$('calibrateBtn').onclick=()=>{for(const k of ['heading','pitch','fov'])$(k).value=cal[k];$('headingOffset').value=cal.offset;$('calibrateDialog').showModal();};
$('calibrateForm').onsubmit=e=>{e.preventDefault();cal={heading:+$('heading').value,pitch:+$('pitch').value,fov:+$('fov').value,offset:+$('headingOffset').value};scene.frozen=null;scene.mark=null;$('markCamera').textContent='▣ Mark opening';$('calibrateDialog').close();scene.draw();};
function sensor(e){if(view!=='camera'||scene.frozen)return;const portrait=(screen.orientation?.angle??window.orientation??0)===0;if(!portrait){$('sensorStatus').textContent='Hold upright in portrait for compass alignment.';return;}let h;if(Number.isFinite(e.webkitCompassHeading))h=e.webkitCompassHeading;else if(e.absolute&&Number.isFinite(e.alpha))h=wrap(360-e.alpha);else{$('sensorStatus').textContent='True heading is unavailable. Use manual calibration.';return;}cal.heading=wrap(h+cal.offset);if(Number.isFinite(e.beta))cal.pitch=clamp(e.beta-90,-80,80);$('heading').value=cal.heading.toFixed(1);$('pitch').value=cal.pitch.toFixed(1);$('sensorStatus').textContent=Number.isFinite(e.webkitCompassAccuracy)&&e.webkitCompassAccuracy>=0?`Compass reports ±${e.webkitCompassAccuracy.toFixed(0)}°. Verify true-north correction and keep roll level.`:'Compass connected. Accuracy is not reported; verify with a known true bearing.';scene.draw();}
function disableSensors(){window.removeEventListener('deviceorientation',sensor);window.removeEventListener('deviceorientationabsolute',sensor);sensorActive=false;}
$('sensorBtn').onclick=async()=>{if(sensorActive){disableSensors();$('sensorBtn').textContent='Enable phone compass';return;}try{if(!window.DeviceOrientationEvent)throw Error('No orientation API');if(typeof DeviceOrientationEvent.requestPermission==='function'){const p=await DeviceOrientationEvent.requestPermission();if(p!=='granted')throw Error('Permission not granted');}window.addEventListener('deviceorientation',sensor);window.addEventListener('deviceorientationabsolute',sensor);sensorActive=true;$('sensorBtn').textContent='Disable phone compass';$('sensorStatus').textContent='Waiting for absolute heading. If none arrives, use manual alignment.';}catch(e){$('sensorStatus').textContent=e.message+'. Use manual heading and pitch.';}};
$('markCamera').onclick=()=>{if(scene.frozen){scene.frozen=null;scene.mark=null;drawMode=false;$('markCamera').textContent='▣ Mark opening';scene.draw();return;}if(!cameraActive){toast('Open the camera first.');return;}const image=document.createElement('canvas');image.width=$('camera').videoWidth;image.height=$('camera').videoHeight;image.getContext('2d').drawImage($('camera'),0,0);scene.frozen={image,cal:{...cal}};drawMode=true;$('markCamera').textContent='Resume camera';$('stageHint').textContent='Frame frozen · Drag a rectangle';scene.draw();};
$('recordBtn').onclick=()=>{if(recorder?.state==='recording'){recorder.stop();return;}if(!cameraActive){toast('Open the camera first.');return;}if(!window.MediaRecorder){toast('Recording is unsupported in this browser. Use your phone camera app.');return;}try{const preferred=['video/mp4','video/webm;codecs=vp8','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(stream,preferred?{mimeType:preferred}:{});const chunks=[];let bytes=0;recorder.ondataavailable=e=>{if(e.data.size){chunks.push(e.data);bytes+=e.data.size;if(bytes>150000000&&recorder.state==='recording')recorder.stop();}};recorder.onerror=()=>toast('Recording failed. Please use the phone camera app.');recorder.onstop=()=>{clearTimeout(recordTimer);$('recordBtn').textContent='● Record walk';$('recordBtn').classList.remove('recording');const mime=recorder.mimeType||preferred||'video/webm';if(chunks.length){download(new Blob(chunks,{type:mime}),'sunlight-walkthrough-'+Date.now()+(mime.includes('mp4')?'.mp4':'.webm'));toast('Walk-through downloaded. Video is a reference, not a reconstructed 3D model.');}else toast('No video was captured.');};recorder.start(1000);$('recordBtn').textContent='■ Stop & save';$('recordBtn').classList.add('recording');recordTimer=setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},120000);toast('Recording video only. Stops after 2 minutes; no audio or automatic 3D reconstruction.');}catch(e){toast('Could not record: '+e.message);}};
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopPlay();if(cameraActive){closeCamera();$('cameraStart').hidden=view!=='camera';scene.draw();}}});
window.addEventListener('pagehide',closeCamera);
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
render();
